export const WS_ROLES = ['admin', 'member', 'guest'];
export const ROLE_RANK = { viewer: 1, developer: 2, lead: 3 };
export const TYPES = ['bug', 'feature', 'task', 'epic', 'subtask'];
export const PRIORITIES = ['urgent', 'high', 'medium', 'low', 'none'];
export const PRIORITY_RANK = { urgent: 0, high: 1, medium: 2, low: 3, none: 4 };
export const CATEGORIES = ['backlog', 'unstarted', 'started', 'completed'];
export const LINK_TYPES = ['blocks', 'relates', 'duplicates'];
export const EVENTS = ['issue.created', 'issue.updated', 'issue.deleted', 'comment.created'];
export const DEFAULT_STATUSES = [
  { name: 'Backlog', category: 'backlog' },
  { name: 'Todo', category: 'unstarted' },
  { name: 'In Progress', category: 'started' },
  { name: 'In Review', category: 'started' },
  { name: 'Done', category: 'completed' },
];
// Issue fields whose changes are recorded in history and replayed for burndown.
export const TRACKED = ['title', 'description', 'type', 'status', 'priority', 'assigneeId', 'labels',
  'storyPoints', 'parentId', 'epicId', 'sprintId', 'dueDate'];

export function defaultTransitions(statuses) {
  const out = [];
  for (const a of statuses) for (const b of statuses) if (a.name !== b.name) out.push([a.name, b.name]);
  return out;
}

export class HttpError extends Error {
  constructor(status, code, message) {
    super(message);
    this.status = status;
    this.code = code;
  }
}
export const bad = (message, code = 'validation_error') => new HttpError(400, code, message);
export const unauthorized = (message = 'Authentication required') => new HttpError(401, 'unauthorized', message);
export const forbidden = (message = 'Forbidden') => new HttpError(403, 'forbidden', message);
export const notFound = (message = 'Not found') => new HttpError(404, 'not_found', message);
export const conflict = (code, message) => new HttpError(409, code, message);
export const rateLimited = (message) => new HttpError(429, 'rate_limited', message);

const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

export const isStr = (v) => typeof v === 'string';
export const isNonEmptyStr = (v) => typeof v === 'string' && v.trim().length > 0;

export function validDate(v) {
  if (!isStr(v) || !DATE_RE.test(v)) return false;
  const t = Date.parse(v + 'T00:00:00Z');
  return !Number.isNaN(t) && new Date(t).toISOString().slice(0, 10) === v;
}

// Inclusive list of YYYY-MM-DD strings from a to b (both UTC).
export function dayRange(a, b) {
  const out = [];
  const end = Date.parse(b + 'T00:00:00Z');
  for (let t = Date.parse(a + 'T00:00:00Z'); t <= end; t += 86400000) {
    out.push(new Date(t).toISOString().slice(0, 10));
  }
  return out;
}

import { scryptSync, randomBytes, createHash, timingSafeEqual } from 'node:crypto';

export function hashPassword(password) {
  const salt = randomBytes(16).toString('hex');
  const hash = scryptSync(password, salt, 64).toString('hex');
  return `scrypt$${salt}$${hash}`;
}

export function verifyPassword(password, stored) {
  const parts = String(stored).split('$');
  if (parts.length !== 3) return false;
  const [, salt, hash] = parts;
  const actual = scryptSync(password, salt, 64);
  const expected = Buffer.from(hash, 'hex');
  return expected.length === actual.length && timingSafeEqual(actual, expected);
}

export const sha256 = (s) => createHash('sha256').update(s).digest('hex');
export const newToken = () => randomBytes(32).toString('base64url');

import { readFileSync, writeFileSync, renameSync, existsSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export function emptyState() {
  return {
    users: [], tokens: [], loginFailures: {},
    workspaces: [], projects: [], issues: [], history: [], links: [], comments: [],
    sprints: [], notifications: [], audit: [], webhooks: [], deliveries: [],
  };
}

export function loadState(file) {
  if (!file || !existsSync(file)) return emptyState();
  return { ...emptyState(), ...JSON.parse(readFileSync(file, 'utf8')) };
}

export function saveState(file, state) {
  if (!file) return;
  mkdirSync(dirname(file), { recursive: true });
  const tmp = file + '.tmp';
  writeFileSync(tmp, JSON.stringify(state));
  renameSync(tmp, file);
}

import { bad } from './errors.js';

// RFC 4180 field escaping.
export function csvEscape(v) {
  if (v === null || v === undefined) return '';
  const s = String(v);
  return /[",\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}

export function toCsv(header, rows) {
  return [header, ...rows].map((r) => r.map(csvEscape).join(',')).join('\r\n') + '\r\n';
}

// Returns [{ line, fields }]; blank lines are skipped. `line` is the 1-based physical line of the row start.
export function parseCsv(text) {
  const s = text.replace(/^﻿/, '');
  const rows = [];
  let fields = [];
  let field = '';
  let inQuotes = false;
  let line = 1;
  let rowLine = 1;
  let i = 0;
  const pushRow = () => {
    fields.push(field);
    rows.push({ line: rowLine, fields });
    fields = [];
    field = '';
  };
  while (i < s.length) {
    const c = s[i];
    if (inQuotes) {
      if (c === '"') {
        if (s[i + 1] === '"') { field += '"'; i += 2; continue; }
        inQuotes = false; i++; continue;
      }
      if (c === '\n') line++;
      field += c; i++; continue;
    }
    if (c === '"') { inQuotes = true; i++; continue; }
    if (c === ',') { fields.push(field); field = ''; i++; continue; }
    if (c === '\r' || c === '\n') {
      if (c === '\r' && s[i + 1] === '\n') i++;
      pushRow();
      line++;
      rowLine = line;
      i++;
      continue;
    }
    field += c; i++;
