    const pr = (await call('POST', `/api/workspaces/${ws.id}/projects`, { name: 'P', key: 'PRJ' }, t)).body;
    const a = await call('POST', `/api/projects/${pr.id}/issues`, { type: 'task', title: 'A', storyPoints: 3 }, t);
