    for (let i = 0; i < 5; i++) {
      assert.equal((await call('POST', '/api/auth/login', { username: 'bob', password: 'wrongwrong' })).status, 401);
    }
    assert.equal((await call('POST', '/api/auth/login', { username: 'bob', password: 'password123' })).status, 429);
