          el('button', { onclick: () => go('sprint', { ws: S.ws.id, p: p.id, id: s.id }) }, 'Report')),
        inS.length ? el('table', {}, el('tbody', {}, inS.map(row))) : el('div', { class: 'muted' }, 'No issues in this sprint.'));
    });
